      {"pointer": "/success_criteria/criteria/0", "excerpt": "https://staging.example/docs serves the new build"},
      {"event_id": "L6", "pointer": "/content/text", "excerpt": "error: ssh: connect to host staging port 22: Connection reset by peer"},
